import os
import random
import numpy as np
import torch


class Config:
    # ==========================================
    # Directories & File Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata CSVs (Generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "validation_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Output Directories
    WORKING_DIR = "./working/idea_6"
    SUBMISSION_DIR = "./submission"
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Model Checkpoint
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # ==========================================
    # Data Configuration
    # ==========================================
    IMG_SIZE = 256

    # Input Channels:
    # 3 channels for Ash Color (Band 11, 14, 15 composite) at t=4
    # 3 channels for Temporal Difference (t=4 minus t=3)
    IN_CHANNELS = 6

    # Temporal context
    N_TIMES_BEFORE = 4
    N_TIMES_AFTER = 3

    # Debugging / Development
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 500  # Number of samples to use when DEBUG is True

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42
    BATCH_SIZE = 32
    EPOCHS = 30

    # Optimizer (AdamW)
    LEARNING_RATE = 3e-4
    WEIGHT_DECAY = 1e-2

    # Scheduler (Cosine Annealing)
    T_MAX = EPOCHS  # For CosineAnnealingLR
    ETA_MIN = 1e-6

    # Loss Weights (Hybrid Loss)
    BCE_WEIGHT = 1.0
    DICE_WEIGHT = 1.0

    # Hardware
    NUM_WORKERS = 2  # Conservative for 12 vCPUs
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # ==========================================
    # Model Architecture
    # ==========================================
    MODEL_NAME = "StripPoolingResNet18UNet"
    BACKBONE = "resnet18"
    ENCODER_WEIGHTS = "imagenet"

    # ==========================================
    # Augmentation (Affine Only)
    # ==========================================
    # Applied via Albumentations
    AUG_PROB = 0.5
    AUG_ROTATE_LIMIT = 20  # degrees
    AUG_SCALE_LIMIT = 0.1  # +/- 10%
    AUG_SHIFT_LIMIT = 0.1  # +/- 10%

    # ==========================================
    # Inference & Post-Processing
    # ==========================================
    USE_TTA = True  # Test Time Augmentation (Flip/Rotate)
    THRESHOLD = 0.5  # Binary mask threshold
    MIN_CONTRAIL_SIZE = 10  # Minimum pixels to keep (from labeling guidance)
    RLE_ORDER = "F"  # Fortran-style (Column-major) flattening for RLE


def setup_system(cfg=Config):
    """
    Initializes the environment:
    1. Creates necessary working and submission directories.
    2. Sets random seeds for full reproducibility.
    """
    # Create directories
    os.makedirs(cfg.WORKING_DIR, exist_ok=True)
    os.makedirs(cfg.SUBMISSION_DIR, exist_ok=True)

    # Set seeds
    random.seed(cfg.SEED)
    np.random.seed(cfg.SEED)
    torch.manual_seed(cfg.SEED)

    if torch.cuda.is_available():
        torch.cuda.manual_seed(cfg.SEED)
        torch.cuda.manual_seed_all(cfg.SEED)
        # Ensure deterministic behavior
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False
